mapper.select:
SELECT DISTINCT RES.ID, IFNULL(MCI.CUSTOMER_NAME,RES.ID) TEXT FROM (SELECT DISTINCT ID FROM (SELECT DISTINCT FP.ISSUER, FP.FINANCIER, FP.MANAGER, FP.SPONSOR, FP.INVEST_ADVISER FROM PTL_SEC_POSITION PSP LEFT JOIN FIN_PRODUCT FP ON PSP.FINPROD_ID = FP.FINPROD_ID WHERE FP.ISSUER IS NOT NULL OR FP.FINANCIER IS NOT NULL OR FP.MANAGER IS NOT NULL OR FP.SPONSOR IS NOT NULL OR FP.INVEST_ADVISER IS NOT NULL) UNPIVOT(ID FOR NAME IN(ISSUER, FINANCIER, MANAGER, SPONSOR, INVEST_ADVISER))) RES LEFT JOIN MST_CUSTOMER_INFO MCI ON RES.ID = MCI.CUSTOMER_ID
and (RES.ID LIKE concat_ws('','%',#{search,jdbcType=VARCHAR},'%') or (MCI.CUSTOMER_NAME LIKE concat_ws('','%',#{search,jdbcType=VARCHAR},'%')))
and RES.ID != #{orgNo,jdbcType=VARCHAR}

select @rownum:=@rownum+1 as rowNumber,
t.seqno,
t.org_no as orgNo,
t.cor_class as corClass,
t.source,
t.executive_name as executiveName,
t.title
from (SELECT @rownum:=0) r,
inf_org_correlation t


		and t.cor_class = #{corClass,jdbcType=VARCHAR}


		and t.org_no = #{orgNo,jdbcType=VARCHAR}


		and t.cor_orgtype = #{corOrgtype,jdbcType=VARCHAR}


		and t.cor_orgid = #{corOrgid,jdbcType=VARCHAR}


		and t.seqno = #{seqno,jdbcType=VARCHAR}


		and t.executive_name = #{executiveName,jdbcType=VARCHAR}


		and t.title = #{title,jdbcType=VARCHAR}
